import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';
import SummaryState from './states/SummaryState';
export default function addSummaryControls() {
  extend(DiscussionControls, 'userControls', function (items, discussion) {
    if (!discussion.canSummarize()) return;
    items.add('summarize', m(Button, {
      icon: "fas fa-wand-magic-sparkles",
      onclick: () => summarize(discussion)
    }, app.translator.trans(`datlechin-ai-summarize.forum.discussion_controls.${discussion.summary() ? 'update' : 'summarize'}_button`)), -10);
  });
  extend(DiscussionControls, 'moderationControls', function (items, discussion) {
    const summary = discussion.summary();
    if (!summary || !summary.canDelete()) return;
    items.add('removeSummary', m(Button, {
      icon: "fas fa-eraser",
      onclick: () => SummaryState.for(discussion).remove()
    }, app.translator.trans('datlechin-ai-summarize.forum.discussion_controls.remove_button')), -10);
  });
}

// The summary sits under the first post, which may not be loaded when the reader is far down the discussion.
function summarize(discussion) {
  const stream = app.current.get('stream');
  stream?.goToFirst();
  SummaryState.for(discussion).generate();
}